const rows = $input.all().map(i => i.json).filter(r => r && r.id != null);
const byLocation = {}; const bySpecialty = {}; const byStatus = {};
for (const r of rows) {
  byLocation[r.location] = (byLocation[r.location] || 0) + 1;
  bySpecialty[r.specialty] = (bySpecialty[r.specialty] || 0) + 1;
  byStatus[r.status] = (byStatus[r.status] || 0) + 1;
}
const fmt = (o) => { const ks = Object.keys(o).sort(); return ks.length ? ks.map(k => "- " + k + ": " + o[k]).join("\n") : "- (sin datos)"; };
const total = rows.length;
const today = $today.toFormat("yyyy-MM-dd");
const recipient = $("Configuracion").first().json.recipient;
const subject = "Resumen operativo FCV " + today + " - " + total + " cita(s) APPROVED";
const body = "Resumen operativo del laboratorio FCV para " + today + " (datos ficticios).\n\n"
  + "Total de citas APPROVED: " + total + "\n\n"
  + "Por sede:\n" + fmt(byLocation) + "\n\n"
  + "Por especialidad:\n" + fmt(bySpecialty) + "\n\n"
  + "Por estado:\n" + fmt(byStatus) + "\n\n"
  + "Nota: el backend expone citas APPROVED del dia; COMPLETED/NO_SHOW/CANCELLED requieren un endpoint adicional.";
return [{ json: { recipient: recipient, subject: subject, body: body, total: total } }];
